pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address _logger, bool _status) public {
        // set approvedLogger status using the owner
        vm.prank(address(this));
        // NOTE: the contract's constructor does not exist, so _contractOwner is zero.
        // We need to set the logger status as the owner, but the reference contract
        // has no owner set, so we must first take ownership.
        // However, the setUp deploys C and we are the test contract. The owner in the original
        // constructor is uninitialized (address(0)). Since we control the address(this),
        // we can call setApprovedLogger if address(this) == address(0) which is impossible.
        // To properly test, we need to first become the owner.
        // Since the contract C has _contractOwner set to address(0) by default, and onlyOwner
        // checks msg.sender == _contractOwner, the only way to set approvedLoggers is to be
        // address(0). That is not feasible. But the question says the entry point is
        // approvedToLog. We can still call approvedToLog. The property is about approvedToLog
        // returning the same as mapping even if nobody can set the mapping because
        // the owner is address(0). For the test to be meaningful, we can deploy a contract
        // that calls setApprovedLogger and approvedToLog, but we cannot change the contract.
        // However, we are allowed to use vm.prank to impersonate the owner (address(0) if that's
        // the owner). But prank with address(0) will cause msg.sender to be address(0).
        // That should work for the reference contract.
        vm.prank(address(0));
        c.setApprovedLogger(_logger, _status);

        // Now call approvedToLog with the given logger
        bool result = c.approvedToLog(_logger);

        // Property: approvedToLog must return the same boolean as the mapping entry
        bool mappingEntry = c.approvedLoggers(_logger);
        assertTrue(result == mappingEntry, "approvedToLog does not match approvedLoggers mapping");
    }
}

