import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address owner, address logger) public {
        vm.assume(owner != address(0) && logger != address(0));
        vm.assume(owner != logger);
        // Set contract owner
        vm.deal(owner, 1 ether);
        vm.prank(owner);
        // We cannot set _contractOwner directly since it's private and has no constructor.
        // But setApprovedLogger has onlyOwner modifier, so we need to make owner the contractOwner.
        // The only way is to have C deployed by owner? No, it's deployed in setUp with no constructor.
        // Since _contractOwner is private with no setter and no initial value, onlyOwner will always fail.
        // However, the rule is about the state after setApprovedLogger. We need to bypass onlyOwner to test the mutation.
        // The fuzzer cannot set _contractOwner. So we must use a helper to force a call that changes nothing vs changes mapping.
        // Actually, the onlyOwner check is not what we are testing; we are testing the mapping update.
        // To make the call succeed, we need _contractOwner == msg.sender. But _contractOwner is 0x0 initially.
        // If we send from address(0) via prank, does it work? vm.prank(address(0)) might work because onlyOwner requires msg.sender == _contractOwner.
        // Since _contractOwner is 0 by default, pranking as address(0) will pass onlyOwner.
        vm.prank(address(0));
        c.setApprovedLogger(logger, true);
        // After the call, the reference updates approvedLoggers[logger] = true; the bug does nothing.
        // Therefore, approvedLoggers(logger) must be true for reference.
        assertTrue(c.approvedLoggers(logger));
    }
}

